from fractions import Fraction
from collections import deque

def solve():
    start = Fraction(11, 3)
    targets = [
        Fraction(7, 3),
        Fraction(11, 4),
        Fraction(2024, 5),
        Fraction(109, 11),
        Fraction(3, 71),
        Fraction(5, 204)
    ]

    queue = deque([(start, 0)])
    visited = {start: 0}

    while queue:
        curr, dist = queue.popleft()

        if curr in targets:
            print(f"Distance of {curr}: {dist}")

        # Neighbors
        neighbors = []
        # T1(x) = -x
        n1 = -curr
        if n1 != curr: neighbors.append(n1)
        # T2(x) = 1-x
        n2 = 1 - curr
        if n2 != curr: neighbors.append(n2)
        # T3(x) = 1/x
        if curr != 0:
            n3 = 1 / curr
            if n3 != curr: neighbors.append(n3)

        for n in neighbors:
            if n not in visited:
                visited[n] = dist + 1
                queue.append((n, dist + 1))

solve()
